import json
import logging
import uuid
import warnings
from json.decoder import JSONDecodeError

import requests
from taf.internal.impact_radar import log_radar

from taf.sw.neat.services.exceptions import JSONParsingError, RequestFailed

logger = logging.getLogger("taf.sw.neat")
logger.addHandler(logging.NullHandler())


class ApiClientLocal(object):
    def __init__(self, configuration, token):
        self.configuration = configuration
        self.token = token
        self.base_url = self.configuration.base_url
        self.session = requests.Session()
        self.session.verify = False

    def _make_request(self, method, uri, **kwargs):
        request_id = uuid.uuid4()
        raw_response = kwargs.pop('raw', False)

        url = self.base_url + uri
        self.session.headers.update({'Authorization': 'Bearer {}'.format(self.token)})
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore")
                self._log_sending_message(request_id, method, url, self.session.headers, kwargs)
                response = self.session.request(method=method, url=url, **kwargs, verify=self.session.verify)
                self._log_received_response(request_id, response, url, method)

            response.raise_for_status()
            try:
                if raw_response:
                    return response
                else:
                    return response.json()
            except JSONDecodeError:
                logger.info('response data type is text')
                return response.text
            except Exception as e:
                raise JSONParsingError('Json conversion failed: {}'.format(e))

        except requests.exceptions.RequestException as e:
            logger.error('Request failed', exc_info=True)
            raise RequestFailed(
                'Request failed: {} | status_code: {} | reason: {} | body: {}'.format(
                    e,
                    getattr(e.response, 'status_code', None),
                    getattr(e.response, 'reason', None),
                    getattr(e.response, 'text', None)
                )
            ) from e

    def _log_sending_message(self, request_id, method, endpoint, headers, payload):
        extra = {
                    "http_request": {
                        "request_id": request_id,
                        "method": method,
                        "url": endpoint,
                        "payload": payload,
                        "headers": headers
                    }
        }

        logger.debug(f"Sending message: {extra}", extra=extra)

        log_radar(
            "Sending NEAT request",
            request_method=method,
            request_url=endpoint,
            request_params=payload.get("params"),
            request_data=payload.get("data"),
            request_json=json.dumps(payload.get("json")),
        )

    def _log_received_response(self, request_id, response, endpoint, method):
        response_content = ' '.join(response.content.decode('utf-8', 'ignore').split())
        if len(response_content) > 1000:
            response_content = response_content[:1000] + '...'

        msg = {
                    "http_response": {
                        "request_id": request_id,
                        "method": method,
                        "url": endpoint,
                        "status_code": response.status_code,
                        "reason": response.reason,
                    }
        }

        extra = msg.copy()
        extra["http_response"]["body"] = response
        msg["http_response"]["body"] = response_content

        logger.debug(f"Received response: {msg}", extra=extra)

    def send_get_request(self, uri, params=None, **kwargs):
        return self._make_request('get', uri, params=params, **kwargs)

    def send_post_request(self, uri, params=None, data=None, json=None, **kwargs):
        return self._make_request('post', uri, params=params, data=data, json=json, **kwargs)

    def send_put_request(self, uri, data=None, json=None, **kwargs):
        return self._make_request('put', uri, data=data, json=json, **kwargs)

    def send_patch_request(self, uri, data=None, json=None, **kwargs):
        return self._make_request('patch', uri, data=data, json=json, **kwargs)

    def send_delete_request(self, uri, **kwargs):
        return self._make_request('delete', uri, **kwargs)
